}

static double render(common_chat_templates * tmpls, int n_tools, int n_props,
                     size_t * out_bytes, const char ** out_status) {
    common_chat_templates_inputs in;
    common_chat_msg msg;
    msg.role    = "user";
    msg.content = "hi";
    in.messages              = {msg};
    in.use_jinja             = true;
    in.add_generation_prompt = true;

    for (int i = 0; i < n_tools; i++) {
        json props = json::object();
        for (int p = 0; p < n_props; p++) {
            props["p" + std::to_string(p)] = {{"type", "string"}, {"description", "d"}};
        }
        common_chat_tool tool;
        tool.name        = "t" + std::to_string(i);
        tool.description = "d";
        tool.parameters  = json{{"type", "object"}, {"properties", props}}.dump();
        in.tools.push_back(tool);
    }

    const auto t0 = std::chrono::steady_clock::now();
    *out_bytes  = 0;
    *out_status = "ok";
    try {
        *out_bytes = common_chat_templates_apply(tmpls, in).prompt.size();
    } catch (const std::exception & e) {
        *out_status = e.what();
    } catch (...) {
        *out_status = "unknown exception";
    }
    return std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
}

int main(int argc, char ** argv) {
    if (argc < 2) {
        printf("usage: poc <template.jinja>\n");
        return 2;
    }
    auto tmpls = common_chat_templates_init(nullptr, slurp(argv[1]));
    if (!tmpls) {
        printf("template init failed\n");
        return 1;
    }

    printf("%7s %7s %10s  %s\n", "tools", "props", "seconds", "render");
    for (auto [nt, np] : {std::pair<int,int>{5,5}, {20,10}, {20,20},
                          {40,30}, {50,50}, {100,100}}) {
        size_t bytes = 0;
        const char * status = "";
        const double dt = render(tmpls.get(), nt, np, &bytes, &status);
        // the outcome sits next to the timing, so the number cannot be mistaken for the
        // cost of throwing rather than the cost of rendering
        printf("%7d %7d %10.3f  [%s, prompt %zu bytes]\n", nt, np, dt, status, bytes);
